using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Security.Cryptography;
using System.Windows.Forms;
using ShareMeRowell;

class InlineSkillChecks {
    static void Require(bool value,string message){if(!value)throw new Exception(message);}
    static IEnumerable<Control> All(Control root){foreach(Control c in root.Controls){yield return c;foreach(var child in All(c))yield return child;}}
    static object Field(object value,string name){return value.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(value);}
    static void Select(AdventurerForm form,int role){All(form).OfType<CharacterTile>().Single(c=>c.RoleIndex==role).PerformClick();Application.DoEvents();}
    static SoftButton Skill(Form form){return All(form).OfType<SoftButton>().Single(c=>c.AccessibleName=="Use character skill");}
    static SoftButton Auto(Form form){return All(form).OfType<SoftButton>().Single(c=>c.AccessibleName=="Automatically use unlocked skills");}
    static void Show(Form form){form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-20000,-20000);form.Show();Application.DoEvents();}
    static void Snapshot(Form form,string path){Application.DoEvents();using(var image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(path);}}
    // Labelled isolated receipts place a fixture one XP below the real unlock, never the owner data.
    static void Seed(string folder,long xp){Directory.CreateDirectory(folder);using(var file=File.Create(Path.Combine(folder,"adventurer.receipts")))using(var sha=SHA256.Create()){
        byte[] header=System.Text.Encoding.ASCII.GetBytes("SMXP001\n");file.Write(header,0,header.Length);int id=0;while(xp>0){int points=(int)Math.Min(50,xp);var data=new byte[44];Array.Copy(BitConverter.GetBytes(++id),data,4);Array.Copy(BitConverter.GetBytes(points*262144L),0,data,32,8);Array.Copy(BitConverter.GetBytes(points),0,data,40,4);file.Write(data,0,data.Length);var hash=sha.ComputeHash(data);file.Write(hash,0,hash.Length);xp-=points;}file.Flush(true);
    }}
    static void Sample(CharacterSkillPreview skill,int position){
        // Deterministic fixture time uses the same playback state as the real timer, without forcing focus.
        ((Timer)Field(skill,"clock")).Stop();var time=(System.Diagnostics.Stopwatch)Field(skill,"time");var player=(SkillPlayback)Field(skill,"playback");long now=time.ElapsedMilliseconds;player.Start(now);player.Update(now,true);player.Update(now+position,false);typeof(CharacterSkillPreview).GetMethod("Activity",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(skill,null);((Timer)Field(skill,"clock")).Stop();skill.Invalidate();
    }
    [STAThread] static int Main(string[] args){try{
        Application.EnableVisualStyles();string folder=Path.GetFullPath(args[0]);Directory.CreateDirectory(folder);var checks=new List<string>();
        var playback=new SkillPlayback();playback.Start(100);playback.Update(100,true);playback.Update(1100,false);Require(playback.Position==1000&&playback.Running,"Playback did not retain its active interval");playback.Update(4100,false);Require(playback.Position==1000,"Inactive time advanced the skill");playback.Update(4100,true);playback.Update(8300,true);Require(playback.Position==5200&&!playback.Running,"Playback did not finish exactly once");playback.Update(30000,true);Require(!playback.Running&&playback.Position==5200,"Finished playback restarted itself");playback.Start(30000);Require(playback.Running&&playback.Position==0,"Manual replay did not reset time");playback.Stop();Require(!playback.Running,"Stop did not end playback");checks.Add("Skill time pauses while inactive, finishes once at5.2seconds, and supports replay and stop");
        var defaults=new HeroProfile();Require(defaults.AutoSkills&& !MadaraSequence.CanAutoUse(defaults,23,95)&&MadaraSequence.CanAutoUse(defaults,23,96)&&!MadaraSequence.CanAutoUse(defaults,0,100),"Automatic use ignored its character/unlock gate");defaults.AutoSkills=false;Require(!MadaraSequence.CanAutoUse(defaults,23,100),"Auto Off was ignored");string legacy=Path.Combine(folder,"legacy-profile");Directory.CreateDirectory(legacy);File.WriteAllText(Path.Combine(legacy,"adventurer.json"),"{\"Name\":\"Legacy courier\",\"Animations\":true,\"PixelPreview\":true}");using(var store=new JourneyStore(legacy))Require(store.Profile.AutoSkills&&store.Profile.PixelPreview&&store.Profile.Name=="Legacy courier","An old profile lost its default or existing preferences");checks.Add("Auto defaults on for old profiles and respects Level96, the selected character and its saved toggle");
        string locked=Path.Combine(folder,"locked-profile");using(var store=new JourneyStore(locked)){
            var p=store.Profile.Copy();p.Animations=true;p.MotionOverride=true;Require(store.SaveProfile(p),"Fixture profile failed");using(var form=new AdventurerForm(store,()=>{})){
                Show(form);Select(form,23);var skill=All(form).OfType<CharacterSkillPreview>().Single();var hero=(Control)Field(form,"hero");Require(!skill.Running,"Locked selection automatically played");int forms=Application.OpenForms.Count;Skill(form).PerformClick();Application.DoEvents();Require(skill.Running&&skill.Visible&&!hero.Visible&&skill.Parent==hero.Parent&&skill.Bounds==hero.Bounds,"Skill did not replace the actual portrait area");Require(Application.OpenForms.Count==forms,"An animation popup was opened");Require(Skill(form).Text=="Stop"&&store.Xp==0&&store.Profile.Role==0,"Manual skill changed equipment or XP");
                Sample(skill,3500);Snapshot(form,Path.Combine(folder,"inline-skill.png"));string frames=Path.Combine(folder,"frames");Directory.CreateDirectory(frames);using(var scene=new MadaraScene())for(int time=0,index=0;time<=MadaraSequence.Duration;time+=50,index++)using(var image=new Bitmap(286,286))using(var g=Graphics.FromImage(image)){scene.Draw(g,new Rectangle(0,0,286,286),new HeroProfile{Role=23},time,true);image.Save(Path.Combine(frames,"frame-"+index.ToString("000")+".png"));}
                All(form).OfType<SoftButton>().Single(b=>b.AccessibleName=="Pixel portrait preview").PerformClick();Require(skill.Running&&skill.Position>=3500,"Changing render mode restarted the skill");Skill(form).PerformClick();Require(!skill.Running&&!skill.Visible&&hero.Visible&&Skill(form).Text=="Use skill","Stop did not restore idle in the same card");
                typeof(Control).GetMethod("OnClick",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(hero,new object[]{EventArgs.Empty});Require(skill.Running,"Clicking Madara did not activate the inline skill");Select(form,0);Require(!skill.Running&&!skill.Visible&&hero.Visible,"Switching characters left a skill running");checks.Add("Locked manual skill and portrait click run inside the existing card with no popup, XP/equip change or render-mode restart");
                Select(form,23);Skill(form).PerformClick();foreach(var size in new[]{form.Size,form.MinimumSize}){form.Size=size;Application.DoEvents();foreach(var control in new Control[]{skill,Skill(form),Auto(form)}){var area=new Rectangle(form.PointToClient(control.PointToScreen(Point.Empty)),control.Size);Require(form.ClientRectangle.Contains(area)&&control.Width>=35&&control.Height>=20,"An inline skill control was clipped");}}Skill(form).PerformClick();form.Close();
            }
        }using(var store=new JourneyStore(locked))Require(store.Profile.Role==0&&store.Xp==0&&store.Profile.PixelPreview,"Preview changed saved progress or lost HD/Pixel");checks.Add("Stop, character switching, default/minimum layout and restart keep the idle portrait, controls and progress intact");
        string unlock=Path.Combine(folder,"unlock-profile");Seed(unlock,Adventure.Threshold(96)-1);using(var store=new JourneyStore(unlock)){
            Require(store.Level==95,"Unlock fixture level is incorrect");var p=store.Profile.Copy();p.Animations=true;p.MotionOverride=true;Require(store.SaveProfile(p),"Unlock profile failed");using(var form=new AdventurerForm(store,()=>{})){
                Show(form);Select(form,23);var skill=All(form).OfType<CharacterSkillPreview>().Single();Require(!skill.Running,"Locked fixture auto-played");long xp=store.Xp;Require(store.AwardVerified(new FileMeta{name="isolated-unlock-fixture.bin",size=262144,sha256=new string('f',64)})==1,"Fixture verified XP did not advance");form.RefreshProgress();Require(store.Level==96&&skill.Running&&store.Xp==xp+1&&store.Profile.Role==0,"Reaching the real unlock did not auto-play without equipping");Require(All(form).OfType<Label>().Any(l=>l.Text=="LEVEL 96"),"Live level display was stale");Skill(form).PerformClick();form.RefreshProgress();Require(!skill.Running,"Ordinary progress refresh replayed the skill");Select(form,0);Select(form,23);Require(skill.Running,"Unlocked card selection did not auto-play");Auto(form).PerformClick();Require(!skill.Running&&!store.Profile.AutoSkills,"Auto Off did not stop and save");Select(form,0);Select(form,23);Require(!skill.Running,"Disabled Auto replayed on selection");Skill(form).PerformClick();Require(skill.Running,"Auto Off blocked manual activation");form.Close();
            }
        }using(var store=new JourneyStore(unlock))Require(!store.Profile.AutoSkills&&store.Level==96&&store.Profile.Role==0,"Auto preference or genuine fixture progression changed after restart");checks.Add("A real95-to96 fixture award starts the selected skill once; unlocked selection auto-plays and Auto Off preserves manual use across restart");
        using(var skill=new CharacterSkillPreview()){Require(!skill.Start(new HeroProfile{Role=23,Animations=false,MotionOverride=true}),"Inline skill bypassed Off");Require(!skill.Start(new HeroProfile{Role=0,Animations=true,MotionOverride=true}),"Another character activated Madara skill");Require(!skill.Playing&&!skill.Running,"A rejected skill started a background timer");}checks.Add("Animation Off and other characters cannot activate an inline scene or background timer");
        File.WriteAllText(Path.Combine(folder,"result.json"),Wire.Encode(new{passed=checks.Count,checks=checks,artifactDirectory=folder,reviewFrames=105,liveFocusForced=false,fixtureTimesUsed=true,ownerProgressUsed=false,phoneUsed=false}));Console.WriteLine(string.Join(Environment.NewLine,checks));return 0;
    }catch(Exception error){Console.Error.WriteLine(error);return 1;}}
}
